"""Verifier for sensor-daily-median. Generated by scripts/build_harbor_tasks.py.

S1 cheap artifact checks, S2 content checks on the manifest of a re-run of
plot.py, S3 delivered PNG == fresh render, S5 sidecar against the answer key.
Machinery: verifier_core.py (adapted from harbor/example/tests/test_state.py).

Known blind spots (the point of the second mutant): nothing here measures
legibility -- tick-label rotation, overlap, clipping at the image edge, or
contrast -- and line dash patterns and legend placement are only partly checked.
"""

from pathlib import Path

import pytest

from verifier_core import (
    APP, DELIVERED_FIGURE, assert_close, axes, bar_containers, check_input_unchanged,
    check_rerender_matches, check_valid_nonblank_png, delivered, find_script, lines,
    load_sidecar, norm_colour, snapshot_delivered, reexecute,
)

INPUTS = {"sensors.csv": "5d32ef74c734788fa1832f75aade3c1d344f2af9b96c7d65f5f8b0109da6518e"}


@pytest.fixture(scope="session")
def manifest():
    snapshot_delivered()
    return reexecute(Path("/tmp/reexec"))


def test_s1_figure_is_a_valid_nonblank_png():
    snapshot_delivered()
    check_valid_nonblank_png()


def test_s1_inputs_unchanged():
    for name, digest in INPUTS.items():
        check_input_unchanged(name, digest)


def test_s1_plotting_script_left_behind():
    assert find_script().stat().st_size > 0


def test_s3_delivered_png_matches_a_fresh_render(manifest):
    check_rerender_matches(manifest)


def png_size():
    from PIL import Image

    with Image.open(delivered(DELIVERED_FIGURE)) as image:
        return image.size

# Blank temp_c rows dropped (not zero), S3 excluded, per-day median / min / max.
KEY = {"dates": ["06-01", "06-02", "06-03", "06-04", "06-05", "06-06", "06-07", "06-08", "06-09", "06-10", "06-11", "06-12", "06-13", "06-14"], "S1_median": [20.98, 20.9, 21.06, 21.13, 21.36, 21.33, 20.98, 21.31, 21.29, 21.185, 21.555, 21.45, 21.25, 21.375], "S2_median": [24.52, 24.94, 25.01, 25.195, 25.27, 25.32, 25.51, 25.54, 25.71, 25.715, 26.22, 26.3, 26.215, 26.71], "S2_min": [17.37, 18.4, 18.24, 18.89, 17.74, 19.14, 19.0, 18.91, 17.92, 19.13, 19.93, 19.43, 18.54, 20.34], "S2_max": [31.11, 32.13, 31.76, 31.93, 31.41, 31.61, 32.01, 32.33, 33.06, 32.5, 31.52, 33.42, 32.87, 32.82]}
TOL = 0.01


def test_s5_sidecar_matches_key():
    declared = load_sidecar()
    assert sorted(declared) == sorted(KEY), f"sidecar keys {sorted(declared)}"
    assert declared["dates"] == KEY["dates"], f"dates {declared['dates']}"
    for name in ("S1_median", "S2_median", "S2_min", "S2_max"):
        assert_close(declared[name], KEY[name], TOL, name)


def test_s2_two_median_lines_with_markers_and_colours(manifest):
    found = {line.get("label"): line for line in lines(manifest)}
    for label, key, colour in (("S1 median", "S1_median", "#1f77b4"), ("S2 median", "S2_median", "#d62728")):
        assert label in found, f"no line labelled {label!r} (lines: {sorted(found)})"
        line = found[label]
        assert_close(line["y"], KEY[key], TOL, f"{label} y values")
        assert line.get("marker") == "o", f"{label} marker is {line.get('marker')!r}, expected circles"
        assert norm_colour(line["colour"]) == colour, f"{label} colour {line['colour']}"


def test_s2_s2_band_spans_daily_min_and_max(manifest):
    bands = [c for c in axes(manifest).get("collections", []) if c.get("label") == "S2 daily range"]
    assert bands, "no shaded collection labelled 'S2 daily range'"
    ys = [y for path in bands[0].get("paths", []) for y in path.get("y", [])]
    for name in ("S2_min", "S2_max"):
        for value in KEY[name]:
            assert any(abs(y - value) <= TOL for y in ys), f"band does not reach {name} value {value}"


def test_s2_axes_text_and_legend(manifest):
    ax = axes(manifest)
    assert [t for t in ax["xticklabels"] if t.strip()] == KEY["dates"], f"x ticks {ax['xticklabels']}"
    assert ax["ylabel"] == "Temperature (°C)"
    assert ax["title"] == "Daily median temperature, S1 vs S2"
    legend = (ax.get("legend") or {}).get("labels", [])
    assert {"S1 median", "S2 median", "S2 daily range"} <= set(legend), f"legend {legend}"
